import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"核心概念","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md"}'),c={name:"guide/concepts.md"};function n(i,e,s,r,l,p){return a(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h1><p>以下概念是理解库集成 API 组织结构的基础。</p><h2 id="文档-printdocument-与「模板」" tabindex="-1">文档（PrintDocument）与「模板」 <a class="header-anchor" href="#文档-printdocument-与「模板」" aria-label="Permalink to &quot;文档（PrintDocument）与「模板」&quot;">​</a></h2><p>一份文档 = 一个可保存为 JSON 的打印模板，包含页面、元素、数据源、页面模板与循环配置。<code>studio.document</code> 管理它；<code>studio.export.json()</code> 序列化。业务上说的「维护模板」就是维护这份 JSON。</p><h2 id="页面-pagenode" tabindex="-1">页面（PageNode） <a class="header-anchor" href="#页面-pagenode" aria-label="Permalink to &quot;页面（PageNode）&quot;">​</a></h2><p>文档由页面数组组成。每页有 <code>width/height</code>（mm）、<code>margins</code>、<code>background</code>、<code>elements</code> 与可选 <code>templateId</code>。<strong>方向由宽高关系表达</strong>：<code>width &gt; height</code> 即横版。元素数组索引 0 在最底层。</p><h2 id="元素-elementnode" tabindex="-1">元素（ElementNode） <a class="header-anchor" href="#元素-elementnode" aria-label="Permalink to &quot;元素（ElementNode）&quot;">​</a></h2><p>页面内容的原子单元：<code>text / rect / ellipse / line / image / barcode / qrcode / table</code> 八种内置类型。通用字段（位置、尺寸、旋转、不透明度、锁定、显隐）+ 类型专属 <code>props</code>。所有元素经注册表驱动，新增类型即注册 <code>ElementDefinition</code>。</p><p><strong>线条是点驱动元素</strong>：几何由 <code>points</code>（页面坐标中的两端点）定义，包围盒为派生值，<code>rotation</code> 恒为 0。</p><h2 id="页面模板-pagetemplate-——不是「模板库」" tabindex="-1">页面模板（PageTemplate）——不是「模板库」 <a class="header-anchor" href="#页面模板-pagetemplate-——不是「模板库」" aria-label="Permalink to &quot;页面模板（PageTemplate）——不是「模板库」&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>API</th></tr></thead><tbody><tr><td>页面模板</td><td>多个页面共用的页眉、页脚、背景等内容</td><td><code>studio.template</code></td></tr><tr><td>模板库</td><td>整份文档的可复用副本</td><td>业务层自行存储 JSON</td></tr></tbody></table><p>页面模板支持继承（<code>baseTemplateId</code>）、双面（<code>facingPages</code> + 偶数页变体）、表尾溢出延续（长表格的溢出行延续到页面模板承载的专属页面）。渲染时模板元素显示在页面元素下方。</p><h2 id="数据源与绑定" tabindex="-1">数据源与绑定 <a class="header-anchor" href="#数据源与绑定" aria-label="Permalink to &quot;数据源与绑定&quot;">​</a></h2><p>数据源（<code>dataSource</code>）声明数据结构与示例数据；绑定把元素属性连到数据字段：</p><ul><li><strong>表达式绑定</strong>：字符串属性内嵌 <span><code>{{ 路径 | 格式化:参数 }}</code></span>。</li><li><strong>结构化绑定</strong>：<code>bindings: { rows: &#39;items&#39; }</code>（表格数组行）；循环成员内直接用行字段与 <code>$index</code>。</li><li><strong>文档变量</strong>：<code>$document.pageNumber/pageCount/now/documentName/pageName</code>。</li></ul><p>渲染时注入的 <code>input</code> 按 <code>key</code> 对应数据源，<strong>不写回模板</strong>。</p><h2 id="循环区块与跟随块" tabindex="-1">循环区块与跟随块 <a class="header-anchor" href="#循环区块与跟随块" aria-label="Permalink to &quot;循环区块与跟随块&quot;">​</a></h2><ul><li><strong>循环区块（RepeatGroup）</strong>：一组元素按数组数据平铺，<code>direction</code> 支持 <code>grid</code> 网格（标签平铺）、<code>page</code> 每条数据一页、<code>vertical</code> 纵向列表，超页自动分页；<code>positionMode: &#39;flow&#39;</code> 时后续内容上移。</li><li><strong>跟随块（FollowBlock）</strong>：元素始终跟随目标（表格 / 循环区块）末尾，间距 <code>gap</code>，签字区场景。</li></ul><h2 id="表格跨页与合计" tabindex="-1">表格跨页与合计 <a class="header-anchor" href="#表格跨页与合计" aria-label="Permalink to &quot;表格跨页与合计&quot;">​</a></h2><ul><li><strong>跨页续排</strong>：<code>pagination.crossPage</code> 开启后长表格自动分页，延续页可重复表头（<code>repeatHeader</code>）。</li><li><strong>补空行</strong>：<code>fillEmptyRows</code> 用空白行补满本页余量；配置 <code>rowsPerPage</code> 时补齐到固定行数。</li><li><strong>合计</strong>：<code>summary</code> 提供每页小计（<code>scope: &#39;eachPage&#39;</code>）与全量合计（<code>scope: &#39;lastPage&#39;</code>）。</li></ul><h2 id="输出与渲染管线" tabindex="-1">输出与渲染管线 <a class="header-anchor" href="#输出与渲染管线" aria-label="Permalink to &quot;输出与渲染管线&quot;">​</a></h2><p>所有输出走同一条管线：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input → 解析绑定 → 文档展开（循环区块物化、自动分页）→ 输出解析器渲染 → HTML / PDF</span></span></code></pre></div><p>展开后的中间结果仍是合法 <code>PrintDocument</code>——HTML / PDF 解析器对绑定无感知。执行后端可选主线程 / Worker / 混合（<code>rendering.worker</code>），<code>execution</code> 字段用于诊断。</p><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>createPrintStudio()  ──mount()──▶ 设计器视图（按需加载，隔离 iframe）</span></span>
<span class="line"><span>      │                     │</span></span>
<span class="line"><span>      │◀──── unmount() ─────┘   只卸视图，实例保留</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>   dispose()  销毁实例（联动 unmount），实例不可再用</span></span></code></pre></div><ul><li><code>mount</code> resolve 即界面与插件就绪；一个实例同时只挂载一个设计器。</li><li><code>usePrintStudio()</code> 本次创建的实例随 Vue 作用域销毁自动 <code>dispose</code>。</li><li>纯输出实例 <code>createPrintRenderer()</code> 用完 <code>dispose()</code>。</li></ul><h2 id="快照语义" tabindex="-1">快照语义 <a class="header-anchor" href="#快照语义" aria-label="Permalink to &quot;快照语义&quot;">​</a></h2><p>所有查询返回快照或句柄：</p><ul><li>句柄：<code>{ id, data, update, remove }</code>；删除后 <code>data</code> 为 <code>undefined</code>。</li><li>集合：<code>list</code> 是属性不是函数；<code>get(ref)</code> 接收 ID 或 <code>{ id }</code> 对象。</li><li>修改必须走句柄 / 集合方法；直接改快照不生效。</li></ul>`,30)])])}const g=o(c,[["render",n]]);export{u as __pageData,g as default};
